st seed=(id='rq1',patch={},targets=settings.seedTargets??['s1','s2'])=>{\n  const r={id,ws_id:'ws1',goal_id:'g1',type:'checkpoint',target_goal_id:null,goal_version:1,note:'Seed note',sender_id:'u1',sender_role:'approver',directive_id:'seed-dir',created_at:at,cancelled_at:null,cancelled_by:null,...patch};\n  const keys=Object.keys(r);db.prepare('INSERT INTO v2_requests ('+keys.join(',')+') VALUES ('+keys.map(()=>'?').join(',')+')').run(...keys.map(k=>r[k]));\n  for(const key of targets){const t={state:'sent',auto_accepted:0,updated_at:at,ended_reason:null,...settings.targetRows?.[key]};db.prepare('INSERT INTO v2_request_targets VALUES (?,?,?,?,?,?,?)').run(r.ws_id,id,key,t.state,t.auto_accepted,t.updated_at,t.ended_reason);}\n };\n if(settings.seed!==false)seed('rq1',settings.row??{});\n for(const[index,patch]of(settings.extraRows??[]).entries())seed(patch.id??'extra'+String(index).padStart(3,'0'),patch,settings.extraTargets??[]);\n if(settings.held)db.prepare('INSERT INTO v2_goal_holds VALUES (?,?,?,?,?,?)').run('ws1','g1',settings.heldBy??'u2',settings.holdReason??'Review needed',at,'hold-seed');\n for(const[keys,time]of(settings.reached??[])){const id='seed-hold-'+time;db.prepare('INSERT OR IGNORE INTO v2_directives VALUES (?,?,?,?,?,?)').run(id,'ws1','g1','hold',JSON.stringify({by:'u2',at:time}),null);for(const key of keys)db.prepare('INSERT OR IGNORE INTO v2_directive_targets VALUES (?,?)').run(id,key);}\n let active=false,reads=0,effects=0,captures=0,transactions=0,commits=0,rollbacks=0,dateReads=0,ids=0,dirs=0,lastRefusal;\n const trace=[],fault=new Error('owned request failure'),wrapped=new WeakMap(),unwrapped=new WeakMap(),sequences=new Map();\n function quiet(fn){const old=active;active=false;try{return fn();}finally{active=old;}}\n function effect(name,args){if(active){trace.push(['service',name,quiet(()=>normalize(args))]);if(++effects===settings.effectFault)throw fault;}}\n function watch(value,label){if(!value||typeof value!=='object')return value;if(wrapped.has(value))return wrapped.get(value);\n  const proxy=new Proxy(value,{get(target,key,receiver){let got;\n   if(active&&typeof key==='string'){trace.push(['get',label,key]);if(++reads===settings.propertyFault)throw fault;const name=label+'.'+key,list=settings.sequences?.[name];if(list){const index=sequences.get(name)??0;sequences.set(name,index+1);got=list[Math.min(index,list.length-1)];}else got=Reflect.get(target,key,receiver);\n   }else got=Reflect.get(target,key,receiver);return watch(got,label+'.'+String(key));\n  },ownKeys(target){if(active)trace.push(['keys',label]);return Reflect.ownKeys(target);}});wrapped.set(value,proxy);unwrapped.set(proxy,value);return proxy;\n }\n const raw=v=>unwrapped.get(v)??v;\n class V2Error extends Error{constructor(status,code,message){effect('newV2Error',[status,code,message]);super(message);this.name='V2Error';this.status=status;this.code=code;}}\n const refusal=(status,code,message)=>lastRefusal=Object.assign(new Error(message),{status,code});\n const call=(name,fn)=>function(...args){assert.equal(this,undefined);effect(name,args);return quiet(()=>fn(...args));};\n const pp=watch({wsId:'ws1',userId:settings.user??'u1',wsRole:settings.role??'member',...(settings.principal??{})},'pp');\n const body=watch(settings.body??{type:'checkpoint',note:'Request note',reason:'Hold reason'},'body');\n const readable=(p,g)=>raw(p).wsId===raw(g).ws_id&&!(settings.hidden??[]).includes(raw(g).id);\n const regex=watch({test(key){assert.equal(this,regex);effect('SESSION_KEY_RE.test',[key]);return /^s[1-3]$/.test(key);}},'SESSION_KEY_RE');\n const supplied={\n  approvalSet:call('approvalSet',g=>watch(settings.approvers?.[raw(g).id]??[raw(g).owner_id],'approvers.'+raw(g).id)),\n  all:call('all',(sql,...args)=>watch(db.prepare(sql).all(...args),'all.'+sql)),\n  audit:call('audit',(...args)=>db.prepare('INSERT INTO fixture_audit VALUES (?,?,?,?,?)').run(...args)),\n  get:call('get',(sql,...args)=>watch(db.prepare(sql).get(...args),'get.'+sql)),