holdRow = (ws, goalId) => get(\"SELECT * FROM v2_goal_holds WHERE ws_id = ? AND goal_id = ?\", ws, goalId);\n    /** Who sends requests and holds for a goal: its approval set, plus every workspace owner. Viewers never. */\n    function canSend(pp, g) {\n        if (pp.wsRole === \"owner\")\n            return true;\n        return pp.wsRole === \"member\" && approvalSet(g).includes(pp.userId);\n    }\n    function requireSender(pp, g, what) {\n        if (pp.wsRole === \"viewer\")\n            throw forbidden(\"read_only\", \"Viewers can look but not change anything.\");\n        if (!canSend(pp, g))\n            throw forbidden(\"not_approver\", `Only someone who can approve for this goal, or a workspace owner, can ${what}.`);\n    }\n    /** A goal as a reader sees it in a request: its title only if they can read it. */\n    function goalRef(pp, ws, goalId) {\n        const g = goalRow(ws, goalId);\n        if (!g || !canReadGoal(pp, goalObj(g)))\n            return { id: null, title: null, version: null, private: true };\n        return { id: g.id, title: g.title, version: g.version };\n    }\n    function sessionKeysIn(b) {\n        const v = b.session_keys;\n        if (v === undefined || v === null)\n            return null;\n        if (!Array.isArray(v))\n            throw badRequest(\"session_keys must be a list\");\n        if (v.length < 1 || v.length > SWITCH_SESSIONS_MAX)\n            throw badRequest(`session_keys: 1 to ${SWITCH_SESSIONS_MAX}`);\n        const out = [];\n        for (const k of v) {\n            if (typeof k !== \"string\" || !SESSION_KEY_RE.test(k))\n                throw badRequest(\"session_keys must be session keys\");\n            if (!out.includes(k))\n                out.push(k);\n        }\n        return out;\n    }\n    /** May this session's owner bind it to `target` now (own goal, their team's goal, or an approved transfer for this\n     *  session), and is the goal active? */\n    function bindableForSession(ws, sessionKey, target) {\n        if (target.status !== \"active\")\n            return false;\n        const s = get(\"SELECT user_id FROM v2_sessions WHERE ws_id = ? AND session_key = ?\", ws, sessionKey);\n        if (!s)\n            return false;\n        const owner = memberPrincipal(ws, s.user_id);\n        return authorize(owner, \"goal.bind\", { kind: \"bind\", goal: goalObj(target), hasTransfer: !!transferFor(ws, sessionKey, target.id) }).ok;\n    }\n    const OPEN_TARGET = \"t.state IN ('sent','received')\";\n    // ---- requests ----\n    /** POST …/goals/{goal}/requests { type, note?, session_keys?, target_goal_id? } -> 201 { request }. */\n    async function sendRequest(pp, goalId, b) {\n        const g = visibleGoal(pp, goalId);\n        requireSender(pp, g, \"send a request to its agents\");\n        const type = oneOf(b, \"type\", REQUEST_TYPES);\n        const note = optStr(b, \"note\", NOTE_MAX);\n        const keys = sessionKeysIn(b);\n        let target = null;\n        if (type === \"switch_goal\") {\n            if (!keys)\n                throw badRequest(\"session_keys is required for switch_goal\");\n            const tid = str(b, \"target_goal_id\", 64);\n            if (tid === g.id)\n                throw badRequest(\"target_goal_id must be another goal\");\n            target = visibleGoal(pp, tid);\n        }\n        else if (b.target_goal_id !== undefined && b.target_goal_id !== null)\n            throw badRequest(\"target_goal_id goes only with switch_goal\");\n        const at = nowIso();\n        const id = await tx(() => {\n            const live = goalRow(pp.wsId, g.id);\n            if (live.status !== \"active\")\n                throw conflict(\"wrong_state\", \"This goal is achieved or dropped, so it takes no requests.\");\n            const onGoal = goalTargets(pp.wsId, g.id);\n            if (keys && keys.some((k) => !onGoal.includes(k)))\n                throw badRequest(\"session_keys must be sessions on this goal\");\n            const targets = keys ?? onGoal;\n            if (!targets.length)\n                throw conflict(\"no_sessions\", \"No shared session is working on this goal, so there is nobody to ask.\");\n            const to = target;\n            if (to && !targets.every((k) => bindableForSession(pp.wsId, k, to))) {\n                throw conflict(\"not_bindable\", \"That goal can't be taken up by every chosen session: it is not active, or a session's owner can't bind it.\");\n            }\n            const open = get(`SELECT 1 AS x FROM v2_requests r WHERE r.ws_id = ? AND r.goal_id = ? AND r.type = ? AND r.cancelled_at IS NULL\n       AND EXISTS (SELECT 1 FROM v2_request_targets t WHERE t.request_id = r.id AND ${OPEN_TARGET})`, pp.wsId, g.id, type);\n            if (open)\n                throw conflict(\"already_open\", \"A request of this type is still waiting for an answer on this goal; cancel it first.\");\n            const sent = get(\"SELECT COUNT(*) AS n FROM v2_requests WHERE sender_id = ? AND created_at > ?\", pp.userId, new (readDate())(readDate().now() - 3600000).toISOString())?.n ?? 0;\n            if (sent >= REQUESTS_PER_HOUR)\n                throw new V2Error(429, \"rate_limited\", \"Too many requests sent in the last hour, try again later\");\n            const rid = newId(\"rq\");\n            const role = approvalSet(live).includes(pp.userId) ? \"approver\" : \"owner\";\n            const dir = writeDirective(pp.wsId, \"request\", targets, null, null, { goalId: g.id, request: { request_id: rid, cancelled: false } });\n            run(`INSERT INTO v2_requests (id, ws_id, goal_id, type, target_goal_id, goal_version, note, sender_id, sender_role, directive_id, created_at)\n       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`, rid, pp.wsId, g.id, type, target?.id ?? null, live.version, note, pp.userId, role, dir, at);\n            for (const k of targets)\n                run(\"INSERT INTO v2_request_targets (ws_id, request_id, session_key, state, updated_at) VALUES (?, ?, ?, 'sent', ?)\", pp.wsId, rid, k, at);\n            audit(pp.wsId, pp.userId, \"request.sent\", rid, at);\n            event(\"first_request\", { ws: pp.wsId, user: pp.userId, props: { type }, at });\n            return rid;\n        });\n        return { request: requestView(pp, g, requestRow(pp.wsId, id)) };\n    }\n    /** DELETE …/requests/{id}: the sender or a workspace owner withdraws it. Sessions that have not answered get a\n     *  `request` directive with cancelled true and their state becomes expired. Cancelling again changes nothing. */\n    async function cancelRequest(pp, goalId, id) {\n        const g = visibleGoal(pp, goalId);\n        if (pp.wsRole === \"viewer\")\n            throw forbidden(\"read_only\", \"Viewers can look but not change anything.\");\n        const r = requestRow(pp.wsId, id);\n        if (!r || r.goal_id !== g.id)\n            throw notFound();\n        if (r.sender_id !== pp.userId && pp.wsRole !== \"owner\")\n            throw forbidden(\"not_sender\", \"Only the person who sent this request, or a workspace owner, can cancel it.\");\n        const at = nowIso();\n        await tx(() => {\n            const cur = requestRow(pp.wsId, id);\n            if (cur.cancelled_at)\n                return;\n            const open = all(`SELECT t.session_key FROM v2_request_targets t WHERE t.request_id = ? AND ${OPEN_TARGET}`, id).map((t) => t.session_key);\n            writeDirective(pp.wsId, \"request\", open, null, null, { goalId: g.id, request: { request_id: id, cancelled: true, reason: \"withdrawn\" } });\n            run(`UPDATE v2_request_targets SET state = 'expired', updated_at = ? WHERE request_id = ? AND state IN ('sent','received')`, at, id);\n            run(\"UPDATE v2_requests SET cancelled_at = ?, cancelled_by = ? WHERE id = ?\", at, pp.userId, id);\n            audit(pp.wsId, pp.userId, \"request.cancelled\", id, at);\n        });\n        return { request: requestView(pp, g, requestRow(pp.wsId, id)) };\n    }\n    /** When a goal is achieved or dropped (inside writeGoalVersion's tx): its requests, and switch_goal requests toward\n     *  it, stop waiting. The sessions still `sent` or `received` get a `request` directive with cancelled true (reason\n     *  goal_closed) and become expired, as on a cancel; sessions that answered keep their answer, and the request is not\n     *  marked cancelled. Each such request is audited request.expired with the person whose action closed the goal. */\n    function expireOpenRequests(ws, goalId, actorId, at) {\n        const open = all(`SELECT r.id, r.goal_id FROM v2_requests r WHERE r.ws_id = ? AND (r.goal_id = ? OR r.target_goal_id = ?) AND r.cancelled_at IS NULL\n     AND EXISTS (SELECT 1 FROM v2_request_targets t WHERE t.request_id = r.id AND ${OPEN_TARGET}) ORDER BY r.created_at, r.id`, ws, goalId, goalId);\n        for (const r of open) {\n            const keys = all(`SELECT t.session_key FROM v2_request_targets t WHERE t.request_id = ? AND ${OPEN_TARGET}`, r.id).map((t) => t.session_key);\n            writeDirective(ws, \"request\", keys, null, null, { goalId: r.goal_id, request: { request_id: r.id, cancelled: true, reason: \"goal_closed\" } });\n            run(`UPDATE v2_request_targets SET state = 'expired', updated_at = ? WHERE request_id = ? AND state IN ('sent','received')`, at, r.id);\n            audit(ws, actorId, \"request.expired\", r.id, at);\n        }\n    }\n    /** A request as the goal page shows it. The sender, the goal's approvers and workspace owners see every session's\n     *  row (owner, repository alias, state); anyone else who reads the goal sees their own sessions' rows and the counts. */\n    function requestView(pp, g, r, approvers = approvalSet(g)) {\n        const rows = all(`SELECT t.session_key, t.state, t.ended_reason, s.state AS session_state, t.auto_accepted, t.updated_at, s.user_id, s.repo_alias, s.harness, s.title, s.started_at\n     FROM v2_request_targets t JOIN v2_sessions s ON s.ws_id = t.ws_id AND s.session_key = t.session_key\n     WHERE t.request_id = ? ORDER BY t.session_key`, r.id);\n        const everyone = r.sender_id === pp.userId || pp.wsRole === \"owner\" || approvers.includes(pp.userId);\n        const count = (...s) => rows.filter((t) => s.includes(t.state)).length;\n        const pending = count(\"sent\", \"received\");\n        const state = r.cancelled_at ? \"cancelled\" : pending ? \"open\" : rows.length && count(\"expired\") === rows.length ? \"expired\" : \"answered\";\n        return {\n            id: r.id,\n            type: r.type,\n            goal: { id: g.id, title: g.title, version: r.goal_version },\n            target_goal: r.target_goal_id ? goalRef(pp, r.ws_id, r.target_goal_id) : null,\n            note: r.note,\n            sender: sender(r),\n            created_at: r.created_at,\n            cancelled_at: r.cancelled_at,\n            cancelled_by: r.cancelled_by ? person(r.cancelled_by) : null,\n            // expired: no session answered before the request stopped waiting, because its goal closed (lib/v2/goals.ts\n            // writeGoalVersion) or because every session it waited on ended (C3-1).\n            state,\n            /** Why an expired request expired: sessions_ended when every session it waited on ended (its device signed out, or\n             *  its person left the workspace) or was stopped by its person (E2E-AGENT cycle 13), else goal_closed. null unless\n             *  state is expired. */\n            expired_reason: state !== \"expired\" ? null : rows.every((t) => t.ended_reason || t.session_state === \"stopped\") ? \"sessions_ended\" : \"goal_closed\",\n            // accepted: the developer's own accepts; not_declined: delivered to the agent and not declined (auto_accepted),\n            // never counted as accepted.\n            counts: {\n                pending,\n                accepted: rows.filter((t) => t.state === \"accepted\" && !t.auto_accepted).length,\n                declined: count(\"declined\"),\n                expired: count(\"expired\"),\n                not_declined: rows.filter((t) => t.state === \"accepted\" && t.auto_accepted).length,\n            },\n            sessions: rows\n                .filter((t) => everyone || t.user_id === pp.userId)\n                .map((t) => ({\n                session_key: t.session_key,\n                owner: person(t.user_id),\n                mine: t.user_id === pp.userId,\n                repo_alias: t.repo_alias,\n                harness: t.harness,\n                title: t.user_id === pp.userId ? t.title : null,\n                /** When the session started: with the key's end, it tells two of one person's sessions in one repository apart (X4). */\n                started_at: t.started_at,\n                state: t.state,\n                ended_reason: t.state === \"expired\" ? t.ended_reason : null,\n                auto_accepted: !!t.auto_accepted,\n                updated_at: t.updated_at,\n            })),\n            can_cancel: !r.cancelled_at && pending > 0 && pp.wsRole !== \"viewer\" && (r.sender_id === pp.userId || pp.wsRole === \"owner\"),\n        };\n    }\n    /** GET …/goals/{goal}/requests: the goal's requests, newest first (at most 50), whether the caller may send one, and\n     *  for a sender the sessions on the goal to pick from. */\n    function listRequests(pp, goalId) {\n        const g = visibleGoal(pp, goalId);\n        const approvers = approvalSet(g);\n        const rows = all(\"SELECT * FROM v2_requests WHERE ws_id = ? AND goal_id = ? ORDER BY created_at DESC, id LIMIT 50\", pp.wsId, g.id);\n        const sender = canSend(pp, g);\n        const sessions = sender\n            ? goalTargets(pp.wsId, g.id).map((k) => {\n                const s = get(\"SELECT user_id, repo_alias, harness, title, started_at FROM v2_sessions WHERE ws_id = ? AND session_key = ?\", pp.wsId, k);\n                // The start time (and, on the sender's own sessions, the title) tells two sessions of one person in one\n                // repository apart in the switch-goal picker. A title is shown only to the session's owner, as on its rows.\n                const mine = s.user_id === pp.userId;\n                return { session_key: k, owner: person(s.user_id), mine, repo_alias: s.repo_alias, harness: s.harness, title: mine ? s.title : null, started_at: s.started_at };\n            })\n            : null;\n        return { requests: rows.map((r) => requestView(pp, g, r, approvers)), can_send: sender && g.status === \"active\", sessions, hold: holdView(pp, g) };\n    }\n    /** A request on the device wire (GET /api/v2/directives, kind request). Goal titles are withheld (null) from a person\n     *  who can no longer read that goal; null when the request no longer exists. A cancelled one says why (cancel_reason\n     *  withdrawn or goal_closed); cancel_reason is null otherwise. */\n    function requestWire(pp, j) {\n        const r = requestRow(pp.wsId, j.request_id);\n        if (!r)\n            return null;\n        const title = (id) => {\n            const g = goalRow(r.ws_id, id);\n            return g && canReadGoal(pp, goalObj(g)) ? { title: g.title, version: g.version } : { title: null, version: g?.version ?? null };\n        };\n        const target = r.target_goal_id ? title(r.target_goal_id) : null;\n        return {\n            id: r.id,\n            type: r.type,\n            cancelled: j.cancelled,\n            cancel_reason: j.cancelled ? (j.reason ?? \"withdrawn\") : null,\n            goal: { id: r.goal_id, title: title(r.goal_id).title, version: r.goal_version },\n            target_goal: r.target_goal_id ? { id: r.target_goal_id, title: target.title, version: target.version } : null,\n            sender: sender(r),\n            note: r.note,\n            created_at: r.created_at,\n        };\n    }\n    /** The requests still waiting on a session its person stopped sharing (Stop sharing, on the web or from a device) expire,\n     *  as for a session that ended (lib/v2/sessions.ts endSessions): no answer is taken from it now. Their targets keep\n     *  `ended_reason` null (a stop by its person, not an end). Inside the caller's tx(). Returns how many expired. */\n    function expireStoppedSessionTargets(ws, sessionKey, at) {\n        return run(\"UPDATE v2_request_targets SET state = 'expired', updated_at = ? WHERE ws_id = ? AND session_key = ? AND state IN ('sent','received')\", at, ws, sessionKey);\n    }\n    /** Move one session's request state on an answer or a delivery receipt (inside the receipt's tx). received after\n     *  sent; accepted or declined while pending; a decline also overrides an accept the agent made on its own, and the\n     *  developer's own accept confirms one (auto_accepted back to 0). A cancelled (expired) or answered request keeps its\n     *  state. auto_accepted on a switch_goal is refused (400): it changes direction, so only the developer accepts it.\n     *  Each answer that changes the state is audited, with the session's person (`actor`) as actor: request.accepted (the\n     *  developer's), request.not_declined (an auto_accepted accept: delivered to the agent, not declined) or\n     *  request.declined. Returns the state. */\n    function requestReceipt(ws, requestId, sessionKey, state, auto, actor) {\n        const r = requestRow(ws, requestId);\n        const t = get(\"SELECT state, auto_accepted FROM v2_request_targets WHERE request_id = ? AND session_key = ?\", requestId, sessionKey);\n        if (!r || !t)\n            return null;\n        if (auto && r.type === \"switch_goal\")\n            throw badRequest(\"A switch_goal request takes effect only when the developer accepts it\");\n        const pending = t.state === \"sent\" || t.state === \"received\";\n        let next = t.state;\n        let flag = t.auto_accepted;\n        if (state === \"received\" && t.state === \"sent\")\n            next = \"received\";\n        else if (state === \"accepted\" && pending)\n            [next, flag] = [\"accepted\", auto ? 1 : 0];\n        else if (state === \"accepted\" && t.state === \"accepted\" && !auto)\n            flag = 0;\n        else if (state === \"declined\" && (pending || (t.state === \"accepted\" && t.auto_accepted)))\n            [next, flag] = [\"declined\", 0];\n        if (next !== t.state || flag !== t.auto_accepted) {\n            const at = nowIso();\n            run(\"UPDATE v2_request_targets SET state = ?, auto_accepted = ?, updated_at = ? WHERE request_id = ? AND session_key = ?\", next, flag, at, requestId, sessionKey);\n            if (next === \"accepted\")\n                audit(ws, actor, flag ? \"request.not_declined\" : \"request.accepted\", requestId, at);\n            else if (next === \"declined\")\n                audit(ws, actor, \"request.declined\", requestId, at);\n        }\n        return next;\n    }\n    // ---- goal holds ----\n    function holdView(pp, g) {\n        const h = holdRow(g.ws_id, g.id);\n        return {\n            held: h ? { held_by: person(h.held_by), reason: h.reason, held_at: h.held_at } : null,\n            can_hold: pp.wsRole !== \"viewer\" && canSend(pp, g),\n        };\n    }\n    /** 404 for a goal the caller can't read, 403 for one they may not hold or release (checked before the recent sign-in\n     *  the hold routes ask for). */\n    function requireHolder(pp, goalId) {\n        requireSender(pp, visibleGoal(pp, goalId), \"hold or release its agents\");\n    }\n    /** GET …/goals/{goal}/hold: whether the goal is held, by whom and why, and whether the caller may hold or release it. */\n    function getHold(pp, goalId) {\n        return holdView(pp, visibleGoal(pp, goalId));\n    }\n    /** PUT …/goals/{goal}/hold { reason? }: hold every session on the goal (a `hold` directive to each). 201 when it\n     *  becomes held; 200 with nothing new when it already is. */\n    async function holdGoal(pp, goalId, b) {\n        const g = visibleGoal(pp, g